    // updateExprVal updates the value of x to val.
    void rec::updateExprVal(Checker* check, ast::Expr x, constant::Value val)
    {
        if(auto [info, ok] = check->untyped[x]; ok)
        {
            info.val = val;
            check->untyped[x] = info;
        }
    }

